def digit_sum(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_n(n):
    # Check if any of the 38 consecutive digit sums are multiples of 11
    for k in range(38):
        m = n + k
        s_m = digit_sum(m)
        if s_m % 11 == 0:
            # P(n) is a multiple of 11
            return False
    # P(n) is not a multiple of 11
    return True

smallest_n = -1
limit = 5000

for n in range(1, limit + 1):
    if check_n(n):
        smallest_n = n
        break

if smallest_n != -1:
    print(f"Smallest n found in range [1, {limit}]: {smallest_n}")
else:
    print(f"No solution found in range [1, {limit}]")

