def S(n):
    """Calculates the sum of the digits of n."""
    return sum(int(d) for d in str(n))

def check_P(n):
    """Calculates P(n) = S(n) * S(n+1) * ... * S(n+37) and checks divisibility by 11."""
    product = 1
    for k in range(38):
        digit_sum = S(n + k)
        product *= digit_sum

    # Check if the product is divisible by 11. 
    # Since 11 is prime, the product is divisible by 11 iff at least one factor is divisible by 11.
    # We only need to check if any S(n+k) is a multiple of 11.
    for k in range(38):
        digit_sum = S(n + k)
        if digit_sum % 11 == 0:
            return True # P(n) IS a multiple of 11
    return False # P(n) is NOT a multiple of 11

# Search range specified by the coordinator: n > 100,000 up to n=1,000,000
start_n = 100001
end_n = 1000001 # Exclusive

found_n = None
for n in range(start_n, end_n):
    if not check_P(n):
        found_n = n
        break

if found_n is not None:
    print(f"Found smallest n: {found_n}")
else:
    print("No solution found in the range [100001, 1000000]")

